 function exportCsv(){const all=lessons(),rows=[['Lesson ID','Class ID','Activity','Subject','Teachers','Student count','Day','Start','End','Room','Locked','State'],...all.map(l=>{const p=project.placements[l.id],index=project.periods.findIndex(r=>r.id===p?.period);return[l.id,l.classId||'',l.name,lookup('subjects',l.subjectId)?.name,names('teachers',l.teacherIds),l.studentIds.length,p?lookup('days',p.day)?.name:'',p?project.periods[index]?.start:'',p?project.periods[index+l.duration-1]?.end:'',p?names('rooms',[p.roomId]):'',p?.locked?'Yes':'No',p?'Placed':'Unassigned'];})];ui.download('wist-timetable.csv',csv(rows));}
