 document.addEventListener('change',ev=>{if(ev.target.id!=='tt-language-source')return;const a=project.activities.find(a=>a.id===ev.target.value),support=project.activities.find(b=>b.languagePartner===a?.id),root=document.querySelector('#tt-language-pupils');if(!a||!support){root.innerHTML='';return;}const ids=[...new Set([...a.studentIds,...support.studentIds])];root.innerHTML='<div class="tt-checkbox-list">'+ids.map(id=>'<label><input type="checkbox" data-language-pupil value="'+esc(id)+'" '+(support.studentIds.includes(id)?'checked':'')+'>'+esc(planningStudents(project).find(s=>s.id===id)?.name||id)+'</label>').join('')+'</div><button class="btn" type="button" id="tt-language-save">Save support pupils</button>';document.querySelector('#tt-language-save').onclick=()=>{try{const selected=[...root.querySelectorAll('[data-language-pupil]:checked')].map(n=>n.value);save(setLanguageSupport(project,a.id,selected),'Parallel language support pupils saved. Regenerate the draft.');}catch(err){ui.toast(err.message);}};});
 document.addEventListener('click',ev=>{const a=ev.target.closest('[data-action]')?.dataset.action;if(!['tt-policy','tt-balance'].includes(a))return;try{init();save(a==='tt-policy'?applySchoolPolicy(project):distributeDepartmentLoads(project),'Planning policy and allocations updated. Review staffing and any input blockers.');}catch(err){ui.toast(err.message);}});
 return{page,action,submit,change,input,async importPlanning(next){try{if(isShared()&&!sharedLoaded)await loadShared();if(isShared()&&!sharedLoaded)return;init();save(next,'Submitted Model 3 choices imported into the planning draft.');}catch(error){ui.toast(error.message);}}};
